import numpy as np, scipy.special as sp
RES=np.array([83,88,222,254,444,495,506,601]); KEEP=np.setdiff1d(np.arange(768),RES)
def gelu(x): return 0.5*x*(1+sp.erf(x/np.sqrt(2)))
def LN(u):
    m=u.mean(-1,keepdims=True); v=((u-m)**2).mean(-1,keepdims=True); return (u-m)/np.sqrt(v+1e-12)
def pool_z(M9, C9, c, mu9, cr=1.0):
    x=c*(M9-mu9)+C9
    x[:,RES]=cr*(M9[:,RES]-mu9[RES])+C9[:,RES]
    return LN(x)
def anchor_dirs(Za):
    A=Za.copy(); A[:,RES]=0
    return A/np.linalg.norm(A,axis=1,keepdims=True)/np.sqrt(768)
def feats(Z, Wd): return gelu(Z@Wd.T)
def pivchol(K, k, tol=1e-8):
    n=K.shape[0]; d=np.diag(K).copy(); L=np.zeros((n,k)); piv=[]
    for i in range(k):
        j=int(np.argmax(d))
        if d[j]<tol*np.diag(K).max():
            rest=[t for t in np.argsort(-np.diag(K)) if t not in set(piv)]
            piv+= rest[:k-len(piv)]; break
        piv.append(j)
        l=(K[:,j]-L[:,:i]@L[j,:i])/np.sqrt(max(d[j],1e-12)); L[:,i]=l; d=d-l**2; d[piv]=-np.inf
    return np.array(piv)
def fit(Phi, Lin, Y, Kaa, lam, c0, jitter=1e-6):
    X=np.concatenate([Phi,Lin],1); mu=X.mean(0); Xc=X-X.mean(0); Ym=Y.mean(0); Yc=Y-Ym
    na=Phi.shape[1]; nl=Lin.shape[1]
    R=np.zeros((na+nl,na+nl)); R[:na,:na]=Kaa+jitter*np.trace(Kaa)/na*np.eye(na); R[na:,na:]=np.eye(nl)/c0
    coef=np.linalg.solve(Xc.T@Xc+lam*R, Xc.T@Yc)
    b=Ym-mu@coef
    return coef, b
